#!/usr/bin/env python3
# generate src/lib/elf/reloc/x86_codes.mach from the vendored LLVM relocation
# lists.
#
# run by hand from anywhere: python3 vendor/llvm/gen-x86-reloc-codes.py
# the build never runs this. the output is deterministic. the LLVM lists are a
# subset of what the psABIs define, so the codes the psABIs add are listed below
# with the psABI that defines them, and a code the LLVM list gains that is also
# listed here is an error.

import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, "..", ".."))
OUT = os.path.join(ROOT, "src", "lib", "elf", "reloc", "x86_codes.mach")

# table, def file, psABI codes the def file lacks
LISTS = [
    ("X86_64", "x86_64.def", "x86-64 psABI", [
        ("R_X86_64_RELATIVE64", 38),
        ("R_X86_64_CODE_5_GOTPCRELX", 46),
        ("R_X86_64_CODE_5_GOTTPOFF", 47),
        ("R_X86_64_CODE_5_GOTPC32_TLSDESC", 48),
        ("R_X86_64_CODE_6_GOTPCRELX", 49),
        ("R_X86_64_CODE_6_GOTPC32_TLSDESC", 51),
    ]),
    ("X86", "i386.def", "i386 psABI", [
        ("R_386_SIZE32", 38),
    ]),
]


def fail(msg):
    sys.exit("gen-x86-reloc-codes: " + msg)


def parse(path):
    with open(path, encoding="utf-8") as f:
        text = f.read()
    return [(m.group(1), int(m.group(2))) for m in re.finditer(r"^ELF_RELOC\((\w+),\s*(\d+)\)", text, re.M)]


def canonical(text):
    res = subprocess.run(["mach", "fmt", "-"], input=text, capture_output=True, text=True)
    if res.returncode != 0:
        fail("mach fmt failed: " + res.stdout + res.stderr)
    return res.stdout


def main():
    out = [
        "# the x86-64 and i386 relocation codes, generated by vendor/llvm/gen-x86-reloc-codes.py",
        "# from the LLVM x86_64.def and i386.def pinned in vendor/llvm/REVISION and the codes",
        "# the psABIs add to them.",
        "",
        "use std.types.size.usize;",
        "use std.types.string.str;",
        "",
        "# one relocation code: its name as the specification spells it, its number and the",
        "# list that defines it",
        "pub rec Code {",
        "    name:   str;",
        "    value:  u32;",
        "    source: str;",
        "}",
        "",
    ]
    for table, defname, abi, extra in LISTS:
        rows = [(n, v, "LLVM " + defname) for n, v in parse(os.path.join(HERE, defname))]
        names = {n for n, _, _ in rows}
        values = {v for _, v, _ in rows}
        for n, v in extra:
            if n in names or v in values:
                fail("psABI code already in the LLVM list: " + n)
            rows.append((n, v, abi))
        if len({n for n, _, _ in rows}) != len(rows) or len({v for _, v, _ in rows}) != len(rows):
            fail("duplicate code in " + table)
        rows.sort(key=lambda r: r[1])
        out.append("pub val %s_COUNT: usize = %d;" % (table, len(rows)))
        out.append("pub val %s: [%s_COUNT]Code = [%s_COUNT]Code{" % (table, table, table))
        for n, v, s in rows:
            out.append('    Code{name: "%s", value: %d, source: "%s"},' % (n, v, s))
        out.append("};")
        out.append("")
    text = canonical("\n".join(out))
    with open(OUT, "w", encoding="utf-8") as f:
        f.write(text)


main()
